import{_ as p,a0 as o,w as l,s as d,ao as c,I as t,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 文件系统中导航的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 文件系统中导航的技巧 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 文件系统中导航的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 文件系统中导航的技巧 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200326 Tricks for getting around your Linux file system","title":"在 Linux 文件系统中导航的技巧","tag":"202005","desc":""},"relativePath":"202005/20200326 Tricks for getting around your Linux file system.md","filePath":"[post].md"}'),r={name:"202005/20200326 Tricks for getting around your Linux file system.md"};function h(g,s,u,k,b,m){const e=o("Link");return l(),d("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-文件系统中导航的技巧" tabindex="-1">在 Linux 文件系统中导航的技巧 <a class="header-anchor" href="#在-linux-文件系统中导航的技巧" aria-label="Permalink to “在 Linux 文件系统中导航的技巧”">​</a></h1><blockquote><p>cd 命令可能是任何 Linux 用户学习的前 10 个命令之一，但这并不是在 Linux 文件系统中导航的唯一方法，这里还有其他一些方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202005/22/114058yrzlx94rz9lbx974.jpg" alt=""></p><p>无论你是在文件系统中四处查看、寻找文件还是尝试进入重要目录，Linux 都可以提供很多帮助。在本文中，我们将介绍一些技巧，使你可以在文件系统中移动，查找和使用所需的命令也更加轻松。</p><h3 id="添加到-path" tabindex="-1">添加到 $PATH <a class="header-anchor" href="#添加到-path" aria-label="Permalink to “添加到 $PATH”">​</a></h3><p>确保你不必花费大量时间在 Linux 系统上查找命令的最简单、最有用的方法之一就是在 <code>$PATH</code> 变量中添加适当的目录。但是，添加到 <code>$PATH</code> 变量中的目录顺序非常重要。它们确定系统在目录中查找要运行命令的目录顺序--在找到第一个匹配项时停止。</p><p>例如，你可能希望将家目录放在第一个，这样，如果你创建的脚本与其他可执行文件有相同的名称，那么只要输入该脚本的名称，它便会运行。</p><p>要将家目录添加到 <code>$PATH</code> 变量中，可以执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export PATH=~:$PATH</span></span></code></pre></div><p><code>~</code> 字符代表家目录。</p><p>如果将脚本保存在 <code>bin</code> 目录中，下面的会有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export PATH=~/bin:$PATH</span></span></code></pre></div><p>然后，你可以运行位于家目录中的脚本，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ myscript</span></span>
<span class="line"><span>Good morning, you just ran /home/myacct/bin/myscript</span></span></code></pre></div><p><strong>重要提示：</strong>上面显示的命令会添加到你的搜索路径中，因为 <code>$PATH</code>（当前路径）被包含在内。它们不会覆盖它。你的搜索路径应该在你的 <code>.bashrc</code> 文件中配置，任何你打算永久化的更改也应该添加到那里。</p><h3 id="使用符号链接" tabindex="-1">使用符号链接 <a class="header-anchor" href="#使用符号链接" aria-label="Permalink to “使用符号链接”">​</a></h3><p>符号链接提供了一种简单而明显的方式来记录可能经常需要使用的目录的位置。例如，如果你管理网站的内容，那么可能需要通过创建如下链接来使你的帐户“记住”网页文件的位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /var/www/html www</span></span></code></pre></div><p>参数的顺序很重要。第一个（<code>/var/www/html</code>）是目标，第二个是你创建的链接的名称。如果你当前不在家目录中，那么以下命令将执行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ln -s /var/www/html ~/www</span></span></code></pre></div><p>设置好之后，你可以使用 <code>cd www</code> 进入 <code>/var/www/html</code>。</p><h3 id="使用-shopt" tabindex="-1">使用 shopt <a class="header-anchor" href="#使用-shopt" aria-label="Permalink to “使用 shopt”">​</a></h3><p><code>shopt</code> 命令还提供了一种让移动到其他目录更加容易的方法。当你使用 <code>shopt</code> 的 <code>autocd</code> 选项时，只需输入名称即可转到目录。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shopt -s autocd</span></span>
<span class="line"><span>$ www</span></span>
<span class="line"><span>cd -- www</span></span>
<span class="line"><span>/home/myacct/www</span></span>
<span class="line"><span>$ pwd -P</span></span>
<span class="line"><span>/var/www/html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ~/bin</span></span>
<span class="line"><span>cd -- /home/myacct/bin</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/myacct/bin</span></span></code></pre></div><p>在上面的第一组命令中，启用了 <code>shopt</code> 命令的 <code>autocd</code> 选项。输入 <code>www</code>，就会调用 <code>cd www</code> 命令。由于此符号链接是在上面的 <code>ln</code> 命令示例之一中创建的，因此将我们移至 <code>/var/www/html</code>。 <code>pwd -P</code> 命令显示实际位置。</p><p>在第二组中，键入 <code>~/bin</code> 会调用 <code>cd</code> 进入在用户家目录的 <code>bin</code> 目录。</p><p>请注意，当你输入的是命令时，<code>autocd</code> 行为将<em>不会</em>生效，即使它也是目录的名称。</p><p><code>shopt</code> 是 bash 内置命令，它有很多选项。这只是意味着你不必在要进入每个目录的名称之前输入 <code>cd</code>。</p><p>要查看 <code>shopt</code> 的其他选项，只需输入 <code>shopt</code>。</p><h3 id="使用-cdpath" tabindex="-1">使用 $CDPATH <a class="header-anchor" href="#使用-cdpath" aria-label="Permalink to “使用 $CDPATH”">​</a></h3><p>可能进入特定目录的最有用技巧之一，就是将你希望能够轻松进入的路径添加到 <code>$CDPATH</code> 中。这将创建一个目录列表，只需输入完整路径名的一部分即可进入。</p><p>一方面，这可能有点棘手。你的 <code>$CDPATH</code> 需要包含要移动到的目录的父目录，而不是目录本身。</p><p>例如，假设你希望仅通过输入 <code>cd html</code> 就可以移至 <code>/var/www/html</code> 目录，并仅使用 <code>cd</code> 和简单目录名即可移至 <code>/var/log</code> 中的子目录。在这种情况下，此 <code>$CDPATH</code> 就可以起作用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ CDPATH=.:/var/log:/var/www</span></span></code></pre></div><p>你将看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd journal</span></span>
<span class="line"><span>/var/log/journal</span></span>
<span class="line"><span>$ cd html</span></span>
<span class="line"><span>/var/www/html</span></span></code></pre></div><p>当你输入的不是完整路径时，<code>$CDPATH</code> 就会生效。它向下查看其目录列表，以查看指定的目录是否存在于其中一个目录中。找到匹配项后，它将带你到那里。</p><p>在 <code>$CDPATH</code> 开头保持 <code>.</code> 意味着你可以进入本地目录，而不必在 <code>$CDPATH</code> 中定义它们。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export CDPATH=&quot;.:$CDPATH&quot;</span></span>
<span class="line"><span>$ Videos</span></span>
<span class="line"><span>cd -- Videos</span></span>
<span class="line"><span>/home/myacct/Videos</span></span></code></pre></div><p>在 Linux 文件系统键切换并不难，但是如果你使用一些方便的技巧轻松地到达各个位置，那你可以节省一些大脑细胞。</p><hr>`,41)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.networkworld.com/article/3533421/tricks-for-getting-around-your-linux-file-system.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3533421/tricks-for-getting-around-your-linux-file-system.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=p(r,[["render",h]]);export{x as __pageData,y as default};
